import{_ as a,o as n,c as p,a3 as t}from"./chunks/framework.Dz5Q8p4s.js";const o=JSON.parse('{"title":"InstructMove: A Text-Indispensable Benchmark for Instruction-Following Manipulation","description":"","frontmatter":{"title":"InstructMove: A Text-Indispensable Benchmark for Instruction-Following Manipulation","arxiv":"2608.22990","date":"2026-08-24","authors":"Mengao Zhao, Ziang Li, Chaodong Huang, Mengchen Ma, Haoyi Jiang, Yiwei Jin, Xinjie Wang, Yun Du, Xuewu Lin, Taojun Ding, Hongyu Xie, Jackson Jiang, Chunlei Yu, Kaihua Zhang, Lichao Huang, Liu Liu, Tianwei Lin, Zhizhong Su","categories":"cs.RO","topics":"视觉语言动作模型, 指令遵循评测, 语言接地","outline":[2,2]},"headers":[],"relativePath":"papers/2608.22990.md","filePath":"papers/2608.22990.md","lastUpdated":null}'),l={name:"papers/2608.22990.md"};function e(i,s,m,r,c,h){return n(),p("div",null,[...s[0]||(s[0]=[t('<h1 id="instructmove-a-text-indispensable-benchmark-for-instruction-following-manipulation" tabindex="-1">InstructMove: A Text-Indispensable Benchmark for Instruction-Following Manipulation <a class="header-anchor" href="#instructmove-a-text-indispensable-benchmark-for-instruction-following-manipulation" aria-label="Permalink to &quot;InstructMove: A Text-Indispensable Benchmark for Instruction-Following Manipulation&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2608.22990" target="_blank" rel="noreferrer">2608.22990</a></td></tr><tr><td><strong>提交日期</strong></td><td>2026-08-24（v1，22 页）</td></tr><tr><td><strong>作者</strong></td><td>Mengao Zhao, Ziang Li, Chaodong Huang, Mengchen Ma, Haoyi Jiang, Yiwei Jin, Xinjie Wang, Yun Du, Xuewu Lin, Taojun Ding, Hongyu Xie, Jackson Jiang, Chunlei Yu, Kaihua Zhang, Lichao Huang, Liu Liu, Tianwei Lin, Zhizhong Su（地平线机器人、问问 AI、东南大学、华科）</td></tr><tr><td><strong>分类</strong></td><td>cs.RO</td></tr><tr><td><strong>一句话</strong></td><td>提出「text-indispensable」这一评测原则——场景里必须有多个视觉与物理上都可行的候选动作、只有一个符合语言指令——并用约束式布局引擎把它实例化成含语义干扰物的 pick-and-place benchmark，配上分阶段指标与反事实指令诊断。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/vla">视觉语言动作模型 VLA</a></p></blockquote><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>VLA 的核心承诺是：同一个场景下，<strong>换一条指令就该换一个动作</strong>。语言必须是功能性必需的变量，而不只是描述性的注脚。</p><p>论文指出的评测缺口是：绝大多数操作 benchmark 的场景里，语义上说得通的目标物体或放置终点<strong>只有一个</strong>。在这种场景里，正确动作可以完全从视觉推出来，指令退化成一个「任务 ID」。于是一个根本不看语言的策略，也能在聚合成功率上拿到漂亮数字，而读者无法从这个数字里读出它到底会不会 grounding。</p><p>这个缺口的代价是实打实的：如果你在这种 benchmark 上宣布「我的 VLA 指令遵循能力提升了 X%」，那个 X 可能全部来自抓取精度的提升，与语言毫无关系。反过来，一个真正改进了语言接地的方法，也可能因为 benchmark 测不出来而被埋掉。</p><p>论文的主张是把这条原则写进 benchmark 的构造过程：一个 episode 必须包含多个<strong>视觉上可信、物理上可执行</strong>的候选动作，而只有一个与指令一致。这样做还有一个副产品：因为多个动作都物理可行，忽略语言的策略仍会去抓某个东西，于是<strong>分阶段归因</strong>变得可解释——伸手伸到干扰物上，是接地错误；伸对了但没抓起来，是控制错误。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p><strong>经典操作 benchmark</strong>（RLBench、CALVIN、VIMA、LIBERO）建立了语言条件操作的训练-评测协议，但场景里目标通常唯一可行，语言的必要性没有被设计进去。<strong>近期 benchmark</strong>（VLABench、SimplerEnv 及其 Instruct 变体、RoboTwin、LIBERO-CF）拓宽了双臂协调、长程规划、sim-to-real 等维度，视觉真实度也更高，论文的 Table 1 把这些维度逐格对比过；但作者认为它们仍未把「语言是否不可或缺」列为显式设计目标。</p><p><strong>空间推理资源</strong>（EmbSpatial-Bench、RoboSpatial）评的是大模型的空间理解，但<strong>不是闭环操作 benchmark</strong>——空间短语不直接决定机器人行为，因此无法回答「策略是否按空间关系去动手」。</p><p><strong>grounding 中间表示路线</strong>（预测框、点、mask、空间先验后再解码动作）在方法层面已经把指令遵循当成 grounding 问题来做，但缺一个能把 grounding 与控制分开计分的测试台。结果就是三种失败混在一起：物体语义错、空间关系错、纯抓取失败。</p><p>InstructMove 的定位是把这份歧义<strong>变成 benchmark 的结构</strong>：用同场景反事实指令测语言依赖，用分阶段指标分离接地与控制。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>在这篇之前已知的事实：(a) VLA 论文普遍报聚合成功率；(b) 有大量轶事说策略「不看语言也能做对」；(c) 桌面场景里目标常常是唯一显著物体；(d) 抓取成功率与目标选择正确率是两个可以分开测的事件。</p><p>从 (c) 出发的推论是：只要保证候选集大小 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">∣</span><span class="mord mathcal" style="margin-right:0.0593em;">G</span><span class="mord">∣</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">≥</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">2</span></span></span></span> 且只有一个匹配指令，视觉可行性就不再能唯一确定答案。这是一个<strong>可以写成约束</strong>的条件，因此可以交给布局引擎去强制满足，而不是靠人工设计场景时的自觉。</p><p>从 (d) 出发的推论是：既然场景里的干扰物是<strong>同类/同属性/同空间族</strong>的，那「伸向了哪一个」这个事件本身就是语言接地的直接读数。于是把成功率拆成 Reach 与 Lift 两半，前者主要读 grounding、后者主要读控制。</p><p>最后一步是自查：怎么知道我造的场景真的是 text-indispensable？答案是<strong>反事实</strong>——固定场景只改指令。如果把指令换成「object」、清空、或换成场景里不存在的物体，策略的行为不变，那它就没在用语言。这个诊断是本文最有价值的部分。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>只要场景里唯一可行的目标就是正确目标，指令遵循就无法被测量——不是测不准，是<strong>原理上不可辨识</strong>。所以要让语言变成必需变量，就必须人为制造「多个都能抓、只有一个对」的局面，并且干扰物必须沿着<strong>指令所用的那个线索</strong>去构造（指令说类别就放跨类别干扰物，说属性就放同类别不同属性的，说空间关系就放同类别不同位置的），否则策略能靠别的捷径绕过去。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p>以 <strong>pick_attribute</strong> 为例：指令 &quot;lift the {attribute} {category}&quot;，场景里放一个目标加两个<strong>同类别但属性不同</strong>（颜色/尺寸/形状/材质）的干扰物。策略无法靠「认出这是个杯子」来解题，必须接地那个属性短语。</p><p><strong>资产库</strong>：基于 EmbodiedGen 资产人工筛选，从 3,253 个物体中选出 1,757 个用于 benchmark 实例化，跨 7 个 domain、18 个 super-category、103 个细粒度类别；属性标注由 VLM 辅助生成并经人工核验（全流程自动化，只对质检标红的资产做人工复核）。</p><p><strong>布局引擎</strong>：约束式生成，强制关系一致性与<strong>目标唯一性</strong>——即保证恰好一个候选满足指令。仿真环境是 NVIDIA Isaac Lab / Isaac Sim。</p><p><strong>四个任务族</strong>：</p><ul><li><em>Pick Category</em>：1 个目标 + 5 个跨类别干扰物；三个 split——seen（换布局与干扰物、复用训练类别）、unseen-instance（类别见过、实例没见过）、unseen-category（类别没见过）。</li><li><em>Pick Attribute</em>：1 个目标 + 2 个同类别干扰物。</li><li><em>Pick Spatial</em>：一个参照物 + 目标 + <strong>同类别</strong>干扰物；关系词表为 left of / right of / in front of / behind / near / far from，均定义在<strong>机器人中心参照系</strong>；布局保证恰好一个候选满足该关系。</li><li><em>Compositional Pick-Place</em>：抓什么和放哪儿<strong>同时</strong>歧义。</li></ul><p><strong>训练-评测协议</strong>：双臂 PiperX 上训 pick_category / pick_attribute / place_a2b，单臂 Franka 上训 pick_spatial / place_a2b。每任务 100 条训练 episode（作者明确说是<strong>刻意用小训练集做有限后训练</strong>，以保留预训练能力），5,000 步，8 张 RTX 5090，最终 checkpoint 直接评测、不做 checkpoint selection。每项指标在 100 个 held-out episode 上评，重复评测波动不超过 5 个百分点。</p><p><strong>反事实诊断</strong>：固定 100 个 pick_category unseen-instance 场景，每个场景在五种指令条件下各跑一遍——Normal、Alternative target（把描述换成场景里另一个可见物体，并把它当作正确目标）、Generic object（只说 &quot;object&quot;）、Empty（清空指令）、Absent object（说一个场景里没有的物体）。前两种报目标条件下的 Reach/Lift，后三种报「是否抓了<strong>任何</strong>物体」。</p><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>本文的形式化不多，但 text-indispensability 的定义本身就是一条约束，值得讲清楚。</p><p>策略是语言条件控制 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">a</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∼</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0278em;">θ</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal">a</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∣</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathnormal">o</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2952em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mrel mtight">≤</span><span class="mord mathnormal mtight">t</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2452em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">ℓ</span><span class="mclose">)</span></span></span></span>，一个 episode 由六元组刻画：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">e</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal">s</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathcal" style="margin-right:0.0278em;">O</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathcal" style="margin-right:0.0278em;">D</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">ℓ</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">g</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.7387em;"><span style="top:-3.113em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mbin mtight">⋆</span></span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathcal" style="margin-right:0.0593em;">G</span><span class="mclose">)</span></span></span></span></span></p><p><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">s</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 初始状态，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathcal" style="margin-right:0.0278em;">O</span></span></span></span> 可操作物体，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathcal" style="margin-right:0.0278em;">D</span></span></span></span> 放置终点，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord">ℓ</span></span></span></span> 指令，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8831em;vertical-align:-0.1944em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">g</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6887em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mbin mtight">⋆</span></span></span></span></span></span></span></span></span></span></span> 指令一致的目标，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7805em;vertical-align:-0.0972em;"></span><span class="mord mathcal" style="margin-right:0.0593em;">G</span></span></span></span> 所有<strong>可信候选</strong>的集合。核心约束是</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">∣</span><span class="mord mathcal" style="margin-right:0.0593em;">G</span><span class="mord">∣</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">≥</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.9331em;vertical-align:-0.1944em;"></span><span class="mord">2</span><span class="mpunct">,</span><span class="mspace" style="margin-right:2em;"></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">g</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.7387em;"><span style="top:-3.113em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mbin mtight">⋆</span></span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.9331em;vertical-align:-0.1944em;"></span><span class="mord mathcal" style="margin-right:0.0593em;">G</span><span class="mpunct">,</span><span class="mspace" style="margin-right:2em;"></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord text"><span class="mord cjk_fallback">只有</span><span class="mord"> </span></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">g</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.7387em;"><span style="top:-3.113em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mbin mtight">⋆</span></span></span></span></span></span></span></span><span class="mord text"><span class="mord"> </span><span class="mord cjk_fallback">匹配</span><span class="mord"> </span></span><span class="mord">ℓ</span><span class="mord">.</span></span></span></span></span></p><p>这三行是整篇论文的技术内核。<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">∣</span><span class="mord mathcal" style="margin-right:0.0593em;">G</span><span class="mord">∣</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">≥</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">2</span></span></span></span> 保证视觉可行性不足以定解；唯一匹配保证语言足以定解。两者合起来，指令就从「可选上下文」变成了「必需变量」。注意 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7805em;vertical-align:-0.0972em;"></span><span class="mord mathcal" style="margin-right:0.0593em;">G</span></span></span></span> 是<strong>可信且物理可执行</strong>的候选集，而不是画面里所有物体——布局引擎的工作正是让干扰物真的进入 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7805em;vertical-align:-0.0972em;"></span><span class="mord mathcal" style="margin-right:0.0593em;">G</span></span></span></span>。</p><p>指标方面，pick-only 用</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9694em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0576em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight"><span class="mord mathrm mtight">pick</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.5</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">⋅</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathbb">I</span><span class="mopen">[</span><span class="mord"><span class="mord mathrm">Reach</span></span><span class="mclose">]</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.5</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">⋅</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathbb">I</span><span class="mopen">[</span><span class="mord"><span class="mord mathrm">Lift</span></span><span class="mclose">]</span></span></span></span></span></p><p>Reach 定义为末端进入到指令一致目标的<strong>预定距离</strong>以内，主要读视觉接地；Lift 为成功抓起并抬升，主要读控制。组合式 pick-and-place 用四项等权：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9694em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.0576em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight"><span class="mord mathrm mtight">pnp</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.2em;vertical-align:-0.35em;"></span><span class="mord">0.25</span><span class="mord"><span class="delimsizing size1">(</span></span><span class="mord mathbb">I</span><span class="mopen">[</span><span class="mord"><span class="mord mathrm">ReachPick</span></span><span class="mclose">]</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathbb">I</span><span class="mopen">[</span><span class="mord"><span class="mord mathrm">LiftPick</span></span><span class="mclose">]</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathbb">I</span><span class="mopen">[</span><span class="mord"><span class="mord mathrm">ReachPlace</span></span><span class="mclose">]</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1.2em;vertical-align:-0.35em;"></span><span class="mord mathbb">I</span><span class="mopen">[</span><span class="mord"><span class="mord mathrm">Place</span></span><span class="mclose">]</span><span class="mord"><span class="delimsizing size1">)</span></span></span></span></span></span></p><p>这种拆分的意义在于：Reach 与 Lift 之间的<strong>落差</strong>是一个可解释量——落差大意味着「找得到但抓不起来」，是控制瓶颈；Reach 本身低意味着接地瓶颈。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p><strong>问题一：现有 VLA 在 text-indispensable 场景下能拿多少？</strong> 设计：<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">0.5</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>、GR00T N1.7、Motus 四个策略走同一训练-评测协议。答案（Reach/Lift，括号内为 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9694em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0576em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight"><span class="mord mathrm mtight">pick</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span></span></span></span>）：pick_category 上 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 0.34/0.04 (0.19)、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">0.5</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 0.82/0.57 (0.69)、GR00T N1.7 0.76/0.17 (0.47)、Motus 0.41/0.10 (0.26)。<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">0.5</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 在语义 pick 任务上定位能力最强，GR00T N1.7 的 Reach 不低但 Lift 很低——「找得到、抓不起」。pick_spatial 上四家 Reach 挤在 0.36–0.51，作者把空间关系接地点名为核心瓶颈。</p><p><strong>问题二：能泛化到没见过的实例与类别吗？</strong> 设计：pick_category 的 unseen-instance / unseen-category split。答案：<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">0.5</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 分别 0.74/0.48 与 0.81/0.54，与 seen split（0.82/0.57）接近；GR00T N1.7 的 Reach 也保持在 0.67–0.70，但 Lift 只有 0.09–0.18。结论是类别接地可以泛化，把定位转成成功操作仍然难。</p><p><strong>问题三：策略真的在用语言吗？</strong> 这是本文最有价值的实验。答案：把目标换成场景里另一个物体（Alternative target），<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">0.5</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 拿到 0.72/0.53，与 Normal 的 0.74/0.48 基本持平——<strong>说明语言确实能重定向目标选择</strong>。但在 Generic / Empty / Absent 三种没有有效目标的条件下，Any-object Reach 高达 0.99–1.00、Any-object Lift 0.64–0.66——<strong>说明语言并不能门控「要不要抓」这个决定</strong>。作者诚实地标注了口径差异：这三种条件跑满评测 horizon，而目标条件的 episode 可能在成功抬起后提前结束，因此两类 Lift 不能直接比。即便如此，结论仍然成立：策略带着一个很强的抓取先验，这与视觉捷径一致。</p><p><strong>问题四：合成数据能迁移到真机吗？</strong> 设计：双臂 PiperX + 一个 D455 俯视 + 两个 D405 腕部相机，仿真侧镜像同样的本体与相机配置；5 个真实物体各 10 次试验共 50 个 episode，每次试验至少放 5 个视觉或语义相似的干扰物；混合训练时每个 batch 按 9:1 采样仿真与真机数据。答案（Reach/Lift，分母 50）：200 真实 19/11，200 仿真 26/11，2,000 仿真 28/15，2,000 仿真 + 200 真实 34/18。同等数据量下仿真的 Reach 更高，作者归因于仿真提供了更大的类内实例与外观多样性。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>5 句话版</strong>：指令遵循在「目标唯一可行」的场景里原理上不可辨识，因为不看语言也能做对；InstructMove 把 text-indispensability 写成硬约束——候选集 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">∣</span><span class="mord mathcal" style="margin-right:0.0593em;">G</span><span class="mord">∣</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">≥</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">2</span></span></span></span>、全部物理可行、只有一个匹配指令——并用约束式布局引擎强制满足；任务被拆成类别识别、属性辨别、空间推理、组合式 pick-and-place 四族，指标拆成 Reach（读接地）与 Lift（读控制）；四个代表性 VLA 的结果显示 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">0.5</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 定位最强而 pick_spatial 是所有模型的共同瓶颈；反事实诊断发现语言能重定向目标、但不能门控是否发起抓取（空指令下 Any-object Reach 仍达 1.00）。</p><p><strong>3 句话版</strong>：如果 benchmark 不满足 text-indispensable，你测的就不是指令遵循。把干扰物沿着指令所用的那条线索去构造，并把成功率拆成「伸对了没」与「抓起来没」，才能把接地失败和控制失败分开。同场景改指令的反事实诊断，应当成为每篇 VLA 论文的标配。</p><p><strong>1 句话版</strong>：语言必须是<strong>必需变量</strong>，否则指令遵循这个指标读不出任何东西。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最脆弱的一条是：<strong>Reach 是语言接地的有效读数</strong>。整套指标体系、四个任务族的诊断价值、以及「pick_spatial 是核心瓶颈」这个结论，全部悬在这个假设上。</p><p>它可能不成立，理由有两层。</p><p>第一层是阈值。Reach 定义为末端进入到目标的「预定距离」以内，但论文<strong>没有给出这个距离的具体数值</strong>，也没有给出干扰物与目标之间的最小间距分布。如果阈值相对物体间距偏松，末端在向任意物体运动的途中经过目标附近就会被计为 Reach，指标就退化成「有没有伸出去」而不是「伸对了没」。</p><p>第二层更要命，是<strong>随机基线缺位</strong>。论文全篇没有报告任何一个「随机选候选」或「不看语言」的策略在四个任务族上的 Reach 分数。基于论文自述的场景构成，可以做一个直接的推断（以下是我的计算，不是论文的声称）：pick_category 是 1 个目标 + 5 个干扰物，随机选中约 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">1/6</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">≈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.17</span></span></span></span>；pick_attribute 是 1 目标 + 2 同类干扰物，随机约 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">1/3</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">≈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.33</span></span></span></span>；pick_spatial 是目标 + 1 个同类别干扰物（参照物不作为抓取候选），随机约 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.5</span></span></span></span>。对照实测：pick_attribute 上 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 的 Reach 是 0.44，只比随机高约 11 个点；<strong>pick_spatial 上四家的 0.36–0.51 全部落在随机水平附近甚至以下</strong>。</p><p>如果这个推断成立，那么「pick_spatial 是瓶颈」这个说法应该被强化成更尖锐的版本：<strong>四个模型在空间关系任务上与随机猜测不可区分</strong>。这不是对 benchmark 的批评——恰恰相反，这正是 benchmark 想暴露的东西——但它是论文本该自己算出来并写进表格的一行。少了这一行，读者会把 0.50 的 Reach 误读成「一半的时候找对了」。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>一周，不需要训练任何策略，只需要跑评测。</p><ol><li>拉起 InstructMove 的仿真环境（代码在 RoboOrchardSim）与四个任务族的 held-out split。</li><li>实现三个<strong>不学习</strong>的对照策略：(a) 随机在候选物体中选一个并伸过去；(b) 永远伸向画面中面积最大的可抓物体；(c) 永远伸向离末端初始位姿最近的可抓物体。三者都不读指令。</li><li>用与论文完全相同的 Reach/Lift 判定，在同样的 100 个 episode 上跑这三个策略，得到四个任务族上的<strong>平凡基线表</strong>。</li><li>顺手记录 Reach 判定所用的距离阈值，以及每个场景里目标与最近干扰物的间距分布。</li></ol><p><strong>判据</strong>：若「随机选」的 Reach 在 pick_spatial 上达到 0.45–0.50，那么论文 Table 2 里该列的全部数字都需要重新解读；若「最近物体」策略在某个任务族上接近 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">0.5</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>，说明该族还残留一条几何捷径，布局约束需要加一条「目标不得系统性地更近」。这个实验成本极低，但它决定了 benchmark 里哪些数字是可读的。</p><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p><strong>替代解释：分数差异主要来自抓取能力，而不是语言接地。</strong></p><p>看 Table 2 的结构：<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">0.5</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 与 GR00T N1.7 的 Reach 相差不大（0.82 vs 0.76、0.81 vs 0.76），但 Lift 相差极大（0.57 vs 0.17、0.62 vs 0.07）。由于 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9694em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0576em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight"><span class="mord mathrm mtight">pick</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span></span></span></span> 把两者等权相加，最终排名（0.69 vs 0.47）主要由 Lift 决定。换句话说，<strong>这个 benchmark 的总排名很大程度上仍在测抓取控制</strong>，而它的立论前提恰恰是要把控制从接地里剥出来。构造反例的方法：只报 Reach 一列重新排名，看四个模型的顺序是否改变；若改变，说明 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9694em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0576em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight"><span class="mord mathrm mtight">pick</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span></span></span></span> 的等权设计把两个正交能力重新混了回去，等权 0.5/0.5 需要被论证而不是默认。</p><p><strong>第二个攻击点：真机迁移实验的干扰物设置与仿真不匹配。</strong> 真机每次试验「至少 5 个视觉或语义相似的干扰物」，而 pick_category 的仿真是 5 个<strong>跨类别</strong>干扰物。两者的难度结构不同（跨类别 vs 相似），因此 Table 5 里 34/50 的 Reach 与 Table 2 里 0.82 的 Reach 不能相互印证。设计：在仿真里复刻真机的「相似干扰物」设置，重跑一遍，看仿真-真机的 Reach 是否对齐。</p><p><strong>第三个攻击点：反事实诊断只在一个 split、一个模型上做过。</strong> Table 4 只覆盖 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">0.5</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 的 pick_category unseen-instance。空指令下 Any-object Reach 1.00 这个结论是否在 pick_spatial、place_a2b 上同样成立，以及 GR00T N1.7 / Motus 是否有同样的抓取先验，论文没有回答。而这恰恰是全篇最有诊断价值的实验——它应该是一张 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">4</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">5</span></span></span></span> 的全表，而不是一行。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p><strong>驱动局限</strong>：InstructMove 仍然以<strong>绝对成功率</strong>作为主要读数。但绝对成功率永远混着控制能力，§11 已经演示了这一点。真正与语言接地一一对应的量，是同一场景下<strong>换指令带来的行为改变量</strong>，而论文已经把测量它所需的全部基础设施（固定场景 + 反事实指令 + 唯一匹配约束）造好了，却只用它做了一次诊断，没有把它变成主指标。</p><p><strong>新 framing</strong>：把指令遵循定义成一个<strong>成对的因果对比量</strong>，而不是一个成功率。对每个场景 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">s</span></span></span></span> 和一对指令 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord"><span class="mord">ℓ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">1</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord">ℓ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">)</span></span></span></span>（分别指向候选集里两个不同的目标 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">g</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">1</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">g</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>），定义语言敏感度</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">Δ</span><span class="mopen">(</span><span class="mord mathnormal">s</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mop">Pr</span><span class="mopen">[</span><span class="mord text"><span class="mord cjk_fallback">选中</span><span class="mord"> </span></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">g</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">1</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∣</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal">s</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord">ℓ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">1</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">]</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mop">Pr</span><span class="mopen">[</span><span class="mord text"><span class="mord cjk_fallback">选中</span><span class="mord"> </span></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">g</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">1</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∣</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal">s</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord">ℓ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">]</span><span class="mord">.</span></span></span></span></span></p><p><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord">Δ</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0</span></span></span></span> 表示完全不看语言（无论说什么都做同一件事），<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord">Δ</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">1</span></span></span></span> 表示完美接地。这个量的关键性质是<strong>它对抓取能力免疫</strong>——只要用「伸向了哪一个候选」作为事件，控制水平会同时出现在被减的两项里而相互抵消。可借鉴的工具来自因果推断里的个体处理效应估计与配对实验设计：指令是 treatment，场景是配对单元。</p><p><strong>第一个实验</strong>：在 pick_category 的 unseen-instance split 上，对每个场景生成指向 6 个候选的 6 条指令，让 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">0.5</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>、GR00T N1.7、Motus 各跑一遍（600 次 rollout / 模型），算出每个模型的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord">Δ</span></span></span></span> 矩阵与其对角占优程度。判据：若某模型的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9694em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0576em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight"><span class="mord mathrm mtight">pick</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span></span></span></span> 排名靠前但 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord">Δ</span></span></span></span> 接近 0，就直接证明了聚合成功率与语言接地的脱钩，也就把 §11 那个「排名由 Lift 决定」的怀疑变成了可发表的结论。顺带能得到一个免费的副产品：<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord">Δ</span></span></span></span> 天然自带随机基线（随机策略的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord">Δ</span></span></span></span> 期望为 0），彻底绕开 §9 里那个没人算过的 chance level 问题。</p>',70)])])}const d=a(l,[["render",e]]);export{o as __pageData,d as default};
